define(["core/ajax","core/notification"],function(Ajax,Notification){"use strict";const init=config=>{const form=document.getElementById("wsg-attempt-form");if(!form)return;let version=Number(config.version||1),dirty=false,filesDirty=false,saving=false;form.querySelectorAll("[data-wsg-code]").forEach(element=>{element.addEventListener("input",()=>{dirty=true}),element.addEventListener("change",()=>{dirty=true})});form.querySelectorAll("[data-wsg-image-input]").forEach(input=>input.addEventListener("change",()=>{filesDirty=Boolean(input.files?.length)||filesDirty;const file=input.files?.[0],panel=input.closest(".wsg-image-upload"),preview=panel?.querySelector(".wsg-image-preview");if(!file||!preview)return;const url=URL.createObjectURL(file);preview.innerHTML="";const image=document.createElement("img");image.className="wsg-uploaded-image",image.src=url,image.alt=`Ảnh vừa chọn ${input.dataset.wsgImageInput}`,image.addEventListener("load",()=>URL.revokeObjectURL(url),{once:true}),preview.appendChild(image),Notification.addNotification({message:'Ảnh đã được chọn. Bấm “Lưu bài” để tải ảnh lên Moodle.',type:"info"})}));const collect=()=>{const result={};return form.querySelectorAll("[data-wsg-code]").forEach(element=>{result[element.dataset.wsgCode]="checkbox"===element.type?element.checked?"1":"0":element.value}),result},save=async()=>{if(!dirty||saving)return;saving=true;try{const requests=Ajax.call([{methodname:"mod_worksheetgrader_save_attempt",args:{attemptid:config.attemptid,answersjson:JSON.stringify(collect()),version:version}}]),result=await requests[0];version=Number(result.version),dirty=false}catch(error){Notification.exception(error)}finally{saving=false}};window.setInterval(save,Math.max(5000,Number(config.interval||1e4))),window.addEventListener("beforeunload",event=>{(dirty||filesDirty)&&(event.preventDefault(),event.returnValue="")}),form.addEventListener("submit",()=>{filesDirty=false,dirty=false})};return{init:init}});
